import{_ as t,o as a,c as r,a0 as o}from"./chunks/framework.BTg7EidG.js";const n="/athanor-docs/screens/world-start.png",s="/athanor-docs/screens/building-info.png",m=JSON.parse('{"title":"The World Map","description":"","frontmatter":{},"headers":[],"relativePath":"guide/world.md","filePath":"guide/world.md"}'),i={name:"guide/world.md"};function h(d,e,l,u,g,c){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="the-world-map" tabindex="-1">The World Map <a class="header-anchor" href="#the-world-map" aria-label="Permalink to &quot;The World Map&quot;">​</a></h1><p><img src="'+n+'" alt="The overworld"></p><p>The world is a globe: march far enough east, west, north or south and you come around the other side. The top bar shows the day, your treasury with net daily change, and the <strong>End Day</strong> button — every unit refreshes its movement, income pays out, and everyone else takes their turn when you press it.</p><h2 id="moving" tabindex="-1">Moving <a class="header-anchor" href="#moving" aria-label="Permalink to &quot;Moving&quot;">​</a></h2><p>Tap your party, then tap a destination: the route appears with numbered <strong>day flags</strong> showing where each travel day ends, and a banner tells you how long the march will take (and what defends the target). <strong>Tap again to march.</strong> Travel orders persist — your party keeps walking each day until it arrives, meets an enemy, or you press <strong>Halt</strong>.</p><h2 id="fog-of-war" tabindex="-1">Fog of war <a class="header-anchor" href="#fog-of-war" aria-label="Permalink to &quot;Fog of war&quot;">​</a></h2><p>You see what your parties and holdings can see. Explored land stays on the map, dimmed, but enemies show only when actually in sight. (The eye button toggles fog for a debug look at the whole world.)</p><h2 id="territory" tabindex="-1">Territory <a class="header-anchor" href="#territory" aria-label="Permalink to &quot;Territory&quot;">​</a></h2><p>Buildings claim the tiles around them, tinted in their owner&#39;s color. Owned tiles pay the building&#39;s income — scaled by how much of its claimed land you actually hold — and friendly ground heals your units every night.</p><h2 id="buildings" tabindex="-1">Buildings <a class="header-anchor" href="#buildings" aria-label="Permalink to &quot;Buildings&quot;">​</a></h2><p><img src="'+s+'" alt="Inspecting a building"></p><p>Tap any building you&#39;ve explored (with no party selected) to inspect it: its name, level, how many floors it rises or delves, what it yields and trains, who holds it, and its story. Your own cities and trainer buildings have their management doors right on the sheet.</p><h2 id="the-blighted-heart" tabindex="-1">The blighted heart <a class="header-anchor" href="#the-blighted-heart" aria-label="Permalink to &quot;The blighted heart&quot;">​</a></h2><p>The center of the world belongs to Entropy: a vast wasteland thick with its fortified holdings, growing crueler the deeper you press — and richer. Garrisons stand harder near the heart, but so does the treasure: the finest relics in the world are found only in the deep blight. The outer wilds are gentler, broken up by <strong>oceans</strong> — water can be crossed, but at a crawl, so plan your marches around the coasts.</p><p>The seven guilds all ring the blight. Everyone is fighting toward the same center; the question is who gets there strongest.</p>',15)])])}const y=t(i,[["render",h]]);export{m as __pageData,y as default};
